/* Haitian Creole Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Jean": "God is gracious — Hebrew, via French", "Marie": "The most common Haitian feminine name.", "Pierre": "rock, stone — Greek petros, via French", "Rose": "rose — Latin, via French", "Jacques": "supplanter — Hebrew Yaakov, via French", "Dieudonne": "God-given — French", "Jean-Baptiste": "A classic Haitian surname from the compound given name.", "Pierre-Louis": "A classic Haitian compound surname.", "Joseph": "A widespread Haitian surname.", "Charles": "A common Haitian surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Jean';
console.log(lookup(q));

